"use client";

import { cn } from "../lib/cn";
import { MOTION_DEFAULTS, type DatePickerMotion } from "../lib/motion";
import { exitDurationForMotion, usePresence } from "../lib/presence";
import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";

export type DatePickerSize = "sm" | "md" | "lg";
export type { DatePickerMotion };

/**
 * ISO calendar date `YYYY-MM-DD` (local calendar parts — no timezone engine).
 */
export type DatePickerProps = {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  size?: DatePickerSize;
  /** Panel enter/exit motion (same recipes as Select). */
  motion?: DatePickerMotion;
  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  disabled?: boolean;
  /** Inclusive min date `YYYY-MM-DD`. */
  min?: string;
  /** Inclusive max date `YYYY-MM-DD`. */
  max?: string;
  name?: string;
  id?: string;
  className?: string;
  placement?: "auto" | "bottom" | "top";
  "aria-label"?: string;
};

const sizeClass: Record<DatePickerSize, string> = {
  sm: "sg-datepicker-trigger-sm",
  md: "",
  lg: "sg-datepicker-trigger-lg",
};

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"] as const;

const ISO_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

type Ymd = { y: number; m: number; d: number };

function parseISO(iso: string | undefined): Ymd | null {
  if (!iso) return null;
  const match = ISO_RE.exec(iso);
  if (!match) return null;
  const y = Number(match[1]);
  const m = Number(match[2]) - 1;
  const d = Number(match[3]);
  if (!Number.isFinite(y) || m < 0 || m > 11 || d < 1 || d > 31) return null;
  const dt = new Date(y, m, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== m || dt.getDate() !== d) {
    return null;
  }
  return { y, m, d };
}

function toISO(y: number, m: number, d: number): string {
  const mm = String(m + 1).padStart(2, "0");
  const dd = String(d).padStart(2, "0");
  return `${y}-${mm}-${dd}`;
}

function ymdToDate({ y, m, d }: Ymd): Date {
  return new Date(y, m, d);
}

function compareISO(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function clampISO(iso: string, min?: string, max?: string): string {
  let next = iso;
  if (min && compareISO(next, min) < 0) next = min;
  if (max && compareISO(next, max) > 0) next = max;
  return next;
}

function isDisabledISO(iso: string, min?: string, max?: string): boolean {
  if (min && compareISO(iso, min) < 0) return true;
  if (max && compareISO(iso, max) > 0) return true;
  return false;
}

function addDays(ymd: Ymd, delta: number): Ymd {
  const dt = ymdToDate(ymd);
  dt.setDate(dt.getDate() + delta);
  return { y: dt.getFullYear(), m: dt.getMonth(), d: dt.getDate() };
}

function addMonths(ymd: Ymd, delta: number): Ymd {
  const dt = new Date(ymd.y, ymd.m + delta, 1);
  const last = new Date(dt.getFullYear(), dt.getMonth() + 1, 0).getDate();
  const d = Math.min(ymd.d, last);
  return { y: dt.getFullYear(), m: dt.getMonth(), d };
}

function formatDisplay(iso: string): string {
  const ymd = parseISO(iso);
  if (!ymd) return iso;
  try {
    return ymdToDate(ymd).toLocaleDateString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  } catch {
    return iso;
  }
}

function formatMonthTitle(y: number, m: number): string {
  try {
    return new Date(y, m, 1).toLocaleDateString(undefined, {
      month: "long",
      year: "numeric",
    });
  } catch {
    return `${m + 1}/${y}`;
  }
}

type Cell = {
  iso: string;
  day: number;
  inMonth: boolean;
};

function buildMonthGrid(viewY: number, viewM: number): Cell[] {
  const first = new Date(viewY, viewM, 1);
  const startPad = first.getDay(); // 0 = Sunday
  const daysInMonth = new Date(viewY, viewM + 1, 0).getDate();
  const cells: Cell[] = [];

  // Leading days from previous month
  const prevLast = new Date(viewY, viewM, 0).getDate();
  for (let i = startPad - 1; i >= 0; i -= 1) {
    const d = prevLast - i;
    const dt = new Date(viewY, viewM - 1, d);
    cells.push({
      iso: toISO(dt.getFullYear(), dt.getMonth(), dt.getDate()),
      day: d,
      inMonth: false,
    });
  }

  for (let d = 1; d <= daysInMonth; d += 1) {
    cells.push({
      iso: toISO(viewY, viewM, d),
      day: d,
      inMonth: true,
    });
  }

  // Trailing to complete weeks (6 rows max keeps height stable)
  while (cells.length % 7 !== 0) {
    const last = cells[cells.length - 1]!;
    const next = addDays(parseISO(last.iso)!, 1);
    cells.push({
      iso: toISO(next.y, next.m, next.d),
      day: next.d,
      inMonth: false,
    });
  }
  while (cells.length < 42) {
    const last = cells[cells.length - 1]!;
    const next = addDays(parseISO(last.iso)!, 1);
    cells.push({
      iso: toISO(next.y, next.m, next.d),
      day: next.d,
      inMonth: false,
    });
  }

  return cells;
}

function CalendarIcon() {
  return (
    <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
      <rect
        x="3.25"
        y="4.5"
        width="13.5"
        height="12.25"
        rx="2.25"
        stroke="currentColor"
        strokeWidth="1.6"
      />
      <path
        d="M3.25 8.25h13.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
      <path
        d="M7 3.25v2.5M13 3.25v2.5"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

function ChevronLeftIcon() {
  return (
    <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
      <path
        d="M12.25 5.5 7.75 10l4.5 4.5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function ChevronRightIcon() {
  return (
    <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
      <path
        d="M7.75 5.5 12.25 10l-4.5 4.5"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/**
 * Atom — DatePicker
 * Single calendar date. Solid trigger + frost month panel.
 * Value is ISO `YYYY-MM-DD` (local calendar; no range/time/locale packs).
 */
export function DatePicker({
  value,
  defaultValue = "",
  onValueChange,
  placeholder = "Pick a date…",
  size = "md",
  motion = MOTION_DEFAULTS.datePicker,
  label,
  hint,
  error,
  disabled,
  min,
  max,
  name,
  id,
  className,
  placement = "auto",
  "aria-label": ariaLabel,
}: DatePickerProps) {
  const reactId = useId();
  const pickerId = id ?? `sg-datepicker-${reactId}`;
  const panelId = `${pickerId}-panel`;
  const hintId = hint ? `${pickerId}-hint` : undefined;
  const errorId = error ? `${pickerId}-error` : undefined;
  const describedBy = [hintId, errorId].filter(Boolean).join(" ") || undefined;
  const invalid = Boolean(error);

  const isControlled = value !== undefined;
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const current = isControlled ? value : uncontrolled;
  const selected = parseISO(current);

  const today = useMemo(() => {
    const now = new Date();
    return toISO(now.getFullYear(), now.getMonth(), now.getDate());
  }, []);

  const [open, setOpen] = useState(false);
  const [menuPlacement, setMenuPlacement] = useState<"bottom" | "top">("bottom");
  const [view, setView] = useState(() => {
    const base = selected ?? parseISO(today)!;
    return { y: base.y, m: base.m };
  });
  const [focusISO, setFocusISO] = useState<string>(() => current || today);
  const { mounted: panelMounted, exiting: panelExiting, state: panelState } =
    usePresence(open, { durationMs: exitDurationForMotion(motion) });

  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);

  const cells = useMemo(
    () => buildMonthGrid(view.y, view.m),
    [view.y, view.m],
  );

  const commit = useCallback(
    (next: string) => {
      const clamped = clampISO(next, min, max);
      if (!isControlled) setUncontrolled(clamped);
      onValueChange?.(clamped);
    },
    [isControlled, max, min, onValueChange],
  );

  const close = useCallback(() => {
    setOpen(false);
  }, []);

  const openPanel = useCallback(() => {
    if (disabled) return;

    if (placement === "top") {
      setMenuPlacement("top");
    } else if (placement === "bottom") {
      setMenuPlacement("bottom");
    } else if (triggerRef.current) {
      const rect = triggerRef.current.getBoundingClientRect();
      const spaceBelow = window.innerHeight - rect.bottom;
      setMenuPlacement(spaceBelow < 320 && rect.top > spaceBelow ? "top" : "bottom");
    }

    const base =
      parseISO(current) ??
      parseISO(clampISO(today, min, max)) ??
      parseISO(today)!;
    setView({ y: base.y, m: base.m });
    setFocusISO(toISO(base.y, base.m, base.d));
    setOpen(true);
  }, [current, disabled, max, min, placement, today]);

  useEffect(() => {
    if (!open || panelExiting) return;

    function onPointerDown(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) {
        close();
      }
    }

    function onDocKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key === "Escape") {
        event.preventDefault();
        close();
        triggerRef.current?.focus();
      }
    }

    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onDocKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onDocKeyDown);
    };
  }, [close, open, panelExiting]);

  useEffect(() => {
    if (!open || panelExiting) return;
    const el = panelRef.current?.querySelector<HTMLElement>(
      `[data-iso="${focusISO}"]`,
    );
    el?.focus({ preventScroll: true });
  }, [focusISO, open, panelExiting, view.y, view.m]);

  function selectISO(iso: string) {
    if (isDisabledISO(iso, min, max)) return;
    commit(iso);
    close();
    triggerRef.current?.focus();
  }

  function moveFocus(deltaDays: number) {
    const cur = parseISO(focusISO) ?? parseISO(today)!;
    let next = addDays(cur, deltaDays);
    let iso = toISO(next.y, next.m, next.d);
    // Skip out-of-range by walking further in the same direction
    let guard = 0;
    while (isDisabledISO(iso, min, max) && guard < 400) {
      next = addDays(next, deltaDays > 0 ? 1 : -1);
      iso = toISO(next.y, next.m, next.d);
      guard += 1;
    }
    if (isDisabledISO(iso, min, max)) return;
    setFocusISO(iso);
    setView({ y: next.y, m: next.m });
  }

  function shiftMonth(delta: number) {
    const focus = parseISO(focusISO) ?? parseISO(today)!;
    const shifted = addMonths(focus, delta);
    const nextView = { y: shifted.y, m: shifted.m };
    let nextFocus = toISO(shifted.y, shifted.m, shifted.d);

    if (isDisabledISO(nextFocus, min, max)) {
      const days = new Date(nextView.y, nextView.m + 1, 0).getDate();
      nextFocus = focusISO;
      for (let d = 1; d <= days; d += 1) {
        const candidate = toISO(nextView.y, nextView.m, d);
        if (!isDisabledISO(candidate, min, max)) {
          nextFocus = candidate;
          break;
        }
      }
    }

    setView(nextView);
    setFocusISO(nextFocus);
  }

  function onTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (disabled) return;

    if (
      event.key === "ArrowDown" ||
      event.key === "ArrowUp" ||
      event.key === "Enter" ||
      event.key === " "
    ) {
      event.preventDefault();
      if (!open) openPanel();
    }
  }

  function onDayKeyDown(event: KeyboardEvent<HTMLButtonElement>, iso: string) {
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      moveFocus(-1);
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      moveFocus(1);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      moveFocus(-7);
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      moveFocus(7);
    } else if (event.key === "PageUp") {
      event.preventDefault();
      shiftMonth(event.shiftKey ? -12 : -1);
    } else if (event.key === "PageDown") {
      event.preventDefault();
      shiftMonth(event.shiftKey ? 12 : 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      const start = toISO(view.y, view.m, 1);
      if (!isDisabledISO(start, min, max)) setFocusISO(start);
    } else if (event.key === "End") {
      event.preventDefault();
      const lastDay = new Date(view.y, view.m + 1, 0).getDate();
      const end = toISO(view.y, view.m, lastDay);
      if (!isDisabledISO(end, min, max)) setFocusISO(end);
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      selectISO(iso);
    }
  }

  const display = current && parseISO(current) ? formatDisplay(current) : null;

  const control = (
    <div className="sg-datepicker-root" ref={rootRef}>
      {name ? <input type="hidden" name={name} value={current} /> : null}

      <button
        ref={triggerRef}
        id={pickerId}
        type="button"
        className={cn(
          "sg-datepicker-trigger",
          sizeClass[size],
          className,
        )}
        disabled={disabled}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={panelId}
        aria-invalid={invalid || undefined}
        aria-describedby={describedBy}
        aria-label={ariaLabel ?? (label ? undefined : "Date")}
        data-open={open || undefined}
        onClick={() => (open ? close() : openPanel())}
        onKeyDown={onTriggerKeyDown}
      >
        <span
          className="sg-datepicker-value"
          data-placeholder={!display || undefined}
        >
          {display ?? placeholder}
        </span>
        <span className="sg-datepicker-icon" aria-hidden="true">
          <CalendarIcon />
        </span>
      </button>

      {panelMounted ? (
        <div
          ref={panelRef}
          id={panelId}
          role="dialog"
          aria-modal="false"
          aria-label={formatMonthTitle(view.y, view.m)}
          className="sg-datepicker-panel"
          data-placement={menuPlacement}
          data-motion={motion}
          data-state={panelState}
        >
          <div className="sg-datepicker-header">
            <button
              type="button"
              className="sg-datepicker-nav"
              aria-label="Previous month"
              onClick={() => shiftMonth(-1)}
            >
              <ChevronLeftIcon />
            </button>
            <div className="sg-datepicker-month" aria-live="polite">
              {formatMonthTitle(view.y, view.m)}
            </div>
            <button
              type="button"
              className="sg-datepicker-nav"
              aria-label="Next month"
              onClick={() => shiftMonth(1)}
            >
              <ChevronRightIcon />
            </button>
          </div>

          <div className="sg-datepicker-weekdays" aria-hidden="true">
            {WEEKDAYS.map((wd) => (
              <span key={wd} className="sg-datepicker-weekday">
                {wd}
              </span>
            ))}
          </div>

          <div className="sg-datepicker-grid" role="grid">
            {Array.from({ length: cells.length / 7 }, (_, week) => (
              <div key={week} className="sg-datepicker-row" role="row">
                {cells.slice(week * 7, week * 7 + 7).map((cell) => {
                  const selectedDay = cell.iso === current;
                  const isToday = cell.iso === today;
                  const focused = cell.iso === focusISO;
                  const dayDisabled = isDisabledISO(cell.iso, min, max);

                  return (
                    <button
                      key={cell.iso}
                      type="button"
                      role="gridcell"
                      tabIndex={focused ? 0 : -1}
                      data-iso={cell.iso}
                      className="sg-datepicker-day"
                      aria-selected={selectedDay}
                      aria-current={isToday ? "date" : undefined}
                      aria-disabled={dayDisabled || undefined}
                      data-selected={selectedDay || undefined}
                      data-today={isToday || undefined}
                      data-outside={!cell.inMonth || undefined}
                      data-focused={focused || undefined}
                      disabled={dayDisabled}
                      onClick={() => selectISO(cell.iso)}
                      onKeyDown={(event) => onDayKeyDown(event, cell.iso)}
                      onFocus={() => setFocusISO(cell.iso)}
                    >
                      {cell.day}
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );

  if (!label && !hint && !error) {
    return control;
  }

  return (
    <div className="sg-field">
      {label ? (
        <label className="sg-field-label" htmlFor={pickerId}>
          {label}
        </label>
      ) : null}
      {control}
      {hint && !error ? (
        <p id={hintId} className="sg-field-hint">
          {hint}
        </p>
      ) : null}
      {error ? (
        <p id={errorId} className="sg-field-error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** ContextMenu panel — same recipes as DropdownMenu / Popover. */
export type ContextMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** DatePicker calendar panel — same recipes as Select. */
export type DatePickerMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
  contextMenu: "scale",
  datePicker: "scale",
} as const satisfies Record<string, string>;

"use client";

import { useEffect, useState } from "react";

/**
 * Unmount delay so CSS exit animations can finish.
 * Keep in sync with token exit durations (~`--sg-duration-normal` / motion-med).
 */
export const EXIT_DURATION_MS = 200;

export type PresenceOptions = {
  /** 0 = unmount immediately (motion="none" or reduced-motion). */
  durationMs?: number;
};

function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Map motion recipe → exit hold time. */
export function exitDurationForMotion(motion: string | undefined): number {
  if (motion === "none") return 0;
  if (prefersReducedMotion()) return 0;
  return EXIT_DURATION_MS;
}

/**
 * Keep a node mounted while `open` is true **and** briefly after it becomes false
 * so exit keyframes can play. Mirrors Radix presence / `data-state` pattern.
 */
export function usePresence(open: boolean, options?: PresenceOptions) {
  const durationMs = options?.durationMs ?? EXIT_DURATION_MS;
  const [mounted, setMounted] = useState(open);
  const [exiting, setExiting] = useState(false);

  useEffect(() => {
    if (open) {
      setMounted(true);
      setExiting(false);
      return;
    }

    if (!mounted) return;

    if (durationMs <= 0) {
      setMounted(false);
      setExiting(false);
      return;
    }

    setExiting(true);
    const id = window.setTimeout(() => {
      setMounted(false);
      setExiting(false);
    }, durationMs);

    return () => window.clearTimeout(id);
  }, [open, durationMs, mounted]);

  return {
    /** Still in the DOM (open or playing exit). */
    mounted,
    /** Exit animation should run. */
    exiting,
    /** For `data-state`: open while interactive, closed while exiting. */
    state: (open && !exiting ? "open" : "closed") as "open" | "closed",
  };
}
